"""Thin wrapper around the authors' fastText trainer.

Preference order (nothing of the authors' code is rewritten, all arguments are
forwarded verbatim to the official Python binding of facebookresearch/fastText):

1. an already importable ``fasttext`` module;
2. ``pip install fasttext-wheel`` (prebuilt binary wheel of the same 0.9.2 code,
   needed on Windows where the native Makefile path requires g++/make);
3. ``pip install <repo>`` (native build of the cloned authors' sources);
4. a clearly-labelled PyTorch EmbeddingBag re-implementation of Figure 1
   (only if 1-3 all fail; then the run is marked as a re-implementation).
"""

import importlib
import os
import shutil
import subprocess
import sys


def _import_fasttext():
    try:
        import fasttext  # noqa: F401
        return importlib.import_module("fasttext")
    except Exception:  # noqa: BLE001
        return None


def _pip(args, timeout=900):
    try:
        p = subprocess.run([sys.executable, "-m", "pip"] + args, capture_output=True,
                           text=True, timeout=timeout)
        return p.returncode == 0, (p.stdout or "") + (p.stderr or "")
    except Exception as e:  # noqa: BLE001
        return False, repr(e)


def repo_git_hash(repo_dir="repo"):
    try:
        p = subprocess.run(["git", "rev-parse", "HEAD"], cwd=repo_dir, capture_output=True,
                           text=True, timeout=60)
        if p.returncode == 0:
            return p.stdout.strip()
    except Exception:  # noqa: BLE001
        pass
    try:
        with open(os.path.join(repo_dir, ".git", "HEAD"), encoding="utf8") as f:
            head = f.read().strip()
        if head.startswith("ref:"):
            with open(os.path.join(repo_dir, ".git", head.split(" ", 1)[1].strip()),
                      encoding="utf8") as f:
                return f.read().strip()
        return head
    except Exception:  # noqa: BLE001
        return None


class Engine:
    def __init__(self):
        self.name = "unset"
        self.provenance = {}
        self._impl = None
        self.reimplementation = False

    # -- engine discovery -------------------------------------------------
    def load(self):
        log = []
        ft = _import_fasttext()
        if ft is not None:
            log.append("fasttext module already importable")
        if ft is None:
            ok, out = _pip(["install", "fasttext-wheel"])
            log.append("pip install fasttext-wheel -> %s" % ok)
            importlib.invalidate_caches()
            ft = _import_fasttext()
        if ft is not None:
            try:
                from importlib.metadata import version
                ver = version("fasttext-wheel")
            except Exception:  # noqa: BLE001
                ver = "unknown"
            self.name = "fasttext-wheel (official facebookresearch/fastText %s Python binding)" % ver
            self.provenance = {"engine": self.name, "module_file": getattr(ft, "__file__", None),
                               "setup_log": log, "git_hash_of_cloned_repo": repo_git_hash()}
            self._impl = ft
            return self
        # native build of the cloned authors' sources
        if os.path.isdir("repo"):
            ok, out = _pip(["install", "."], timeout=900)
            log.append("pip install repo/ -> %s" % ok)
            importlib.invalidate_caches()
            ft = _import_fasttext()
        if ft is None and os.path.isdir("repo"):
            try:
                subprocess.run(["make"], cwd="repo", capture_output=True, timeout=900)
            except Exception:  # noqa: BLE001
                pass
            log.append("repo make attempted (g++/make: %s/%s)" % (shutil.which("g++"), shutil.which("make")))
            importlib.invalidate_caches()
            ft = _import_fasttext()
        if ft is None:
            from embeddingbag_fallback import EmbeddingBagEngine
            self._impl = EmbeddingBagEngine()
            self.name = "pytorch EmbeddingBag re-implementation (authors' fastText unavailable)"
            self.reimplementation = True
            self.provenance = {"engine": self.name, "setup_log": log,
                               "git_hash_of_cloned_repo": repo_git_hash()}
            return self
        self.name = "native build of cloned facebookresearch/fastText sources"
        self.provenance = {"engine": self.name, "setup_log": log,
                           "git_hash_of_cloned_repo": repo_git_hash()}
        self._impl = ft
        return self

    # -- training / testing ----------------------------------------------
    def train(self, input, output, **kwargs):
        """Forward everything verbatim to fasttext.train_supervised / fallback."""
        if self.reimplementation:
            self._impl.train(input=input, output=output, **kwargs)
            return self._impl
        kwargs = dict(kwargs)
        # optional args the installed binding may not know about
        try:
            return self._impl.train_supervised(input=input, output=output, **kwargs)
        except (TypeError, ValueError):
            for opt in ("seed", "verbose"):
                kwargs.pop(opt, None)
            return self._impl.train_supervised(input=input, output=output, **kwargs)

    def test(self, model, path):
        if self.reimplementation:
            return model.test(path)
        return model.test(path)

